$t['The broadcast was interrupted. Please try again.'] = 'Vysílání bylo přerušeno. Zkuste to prosím znovu.';
$t['The camera or microphone request was interrupted. Please try again.'] = 'Požadavek na kameru nebo mikrofon byl přerušen. Zkuste to prosím znovu.';
