$t['The check could not finish. Reload the page and try again.'] = 'Kontrolu se nepodařilo dokončit. Obnovte stránku a zkuste to znovu.';
$t['The comment is empty'] = 'The comment is empty';
$t['The commit identifies the Git revision checked out on this server; local file edits are not included. A Git tag is shown when one points directly to that commit.'] = 'Commit určuje revizi Gitu nasazenou na tomto serveru; lokální úpravy souborů nejsou zahrnuty. Tag Gitu se zobrazí, pokud ukazuje přímo na tento commit.';
$t['The Companion Chat service is not available right now. Ask your site administrator to check the AI plugin connection.'] = 'Služba Companion Chat není momentálně dostupná. Požádejte administrátora webu o kontrolu připojení pluginu AI.';
$t['The connection could not be renewed. Please reconnect your account.'] = 'Připojení se nepodařilo obnovit. Připojte prosím svůj účet znovu.';
$t['The connection expired and could not be renewed. Please reconnect your account.'] = 'Platnost připojení vypršela a nepodařilo se ho obnovit. Připojte prosím svůj účet znovu.';
$t['The connection to the destination was dropped mid-stream. This may be a temporary network issue; FFMPEG will try to reconnect.'] = 'Spojení s cílem bylo během streamu přerušeno. Může jít o dočasný problém se sítí; FFMPEG se pokusí znovu připojit.';
$t['The connection to YouTube was interrupted. The upload was paused and can be resumed.'] = 'Spojení s YouTube bylo přerušeno. Nahrávání bylo pozastaveno a lze v něm pokračovat.';
$t['The connection was interrupted. Check your account before retrying this subscription.'] = 'Spojení bylo přerušeno. Před opakováním tohoto předplatného zkontrolujte svůj účet.';
$t['The connection was renewed.'] = 'Připojení bylo obnoveno.';
$t['The connection window was closed before the authorization finished. No account was connected.'] = 'Okno připojení bylo zavřeno před dokončením autorizace. Žádný účet nebyl připojen.';
$t['The converted files were kept. Contact the site administrator to retry the transfer; you do not need to upload the video again.'] = 'Převedené soubory byly zachovány. Kontaktujte administrátora webu, aby přenos zopakoval; video není nutné nahrávat znovu.';
$t['The converted video could not be sent back to this site.'] = 'Převedené video se nepodařilo odeslat zpět na tento web.';
$t['The customers of the selected card. Search, sort, copy the e-mails or export everything to a spreadsheet.'] = 'Zákazníci vybrané karty. Vyhledávejte, řaďte, kopírujte e-maily nebo vše exportujte do tabulky.';
$t['The daily YouTube upload quota of this website was reached. Uploads become available again after midnight Pacific Time. Please try again later.'] = 'Denní kvóta nahrávání na YouTube pro tento web byla vyčerpána. Nahrávání bude znovu dostupné po půlnoci tichomořského času. Zkuste to prosím později.';
$t['The database version changes only when a database migration is applied. It is not expected to match the release tag or commit.'] = 'Verze databáze se mění pouze při provedení migrace databáze. Neočekává se, že bude odpovídat tagu vydání nebo commitu.';
$t['The default'] = 'Výchozí';
$t['The destination RTMP server refused the connection. Check the stream URL and make sure the server is online.'] = 'Cílový RTMP server odmítl připojení. Zkontrolujte URL streamu a ověřte, že je server online.';
$t['The destination server requires authentication. Check the stream key.'] = 'Cílový server vyžaduje ověření. Zkontrolujte klíč streamu.';
$t['The destination server returned 403. The stream key may be invalid or expired.'] = 'Cílový server vrátil chybu 403. Klíč streamu může být neplatný nebo vypršel.';
$t['The destination video was removed or this account cannot edit it. Check the video and account access on the site.'] = 'Cílové video bylo odstraněno nebo jej tento účet nemůže upravovat. Zkontrolujte video a přístup účtu na webu.';
$t['The download is controlled by the system, there is nothing to check on the user'] = 'The download is controlled by the system, there is nothing to check on the user';
$t['The download permission is site wide, so there is nothing to check on the video'] = 'Oprávnění ke stahování platí pro celý web, u videa tedy není co kontrolovat';
$t['The download permission is site wide, so there is nothing to check onthe video'] = 'The download permission is site wide, so there is nothing to check onthe video';
$t['The email is invalid'] = 'The email is invalid';
$t['The encoder could not download the original file.'] = 'Enkodér nemohl stáhnout původní soubor.';
$t['The encoder could not find this video on the site.'] = 'Enkodér nenašel toto video na webu.';
$t['The encoder did not confirm that the video was added to the queue. Please retry.'] = 'Enkodér nepotvrdil přidání videa do fronty. Zkuste to prosím znovu.';
$t['The encoder is running out of disk space'] = 'Enkodéru dochází místo na disku';
$t['The encoder reported an unexpected error.'] = 'Enkodér nahlásil neočekávanou chybu.';
$t['The encoding process stopped unexpectedly, and the automatic retries also failed.'] = 'Proces kódování se neočekávaně zastavil a automatické opakování také selhalo.';
$t['The encoding queue is stalled'] = 'Fronta kódování se zasekla';
$t['The event purchase could not be completed. Your wallet payment was not deducted. Check your balance before trying again.'] = 'Nákup události se nepodařilo dokončit. Platba z peněženky nebyla stržena. Před dalším pokusem zkontrolujte svůj zůstatek.';
$t['The file could not be converted. It may be damaged or use a format the encoder does not support.'] = 'Soubor se nepodařilo převést. Může být poškozený nebo používat formát, který enkodér nepodporuje.';
$t['The file must be an .vtt file!'] = 'Soubor musí být .vtt!';
$t['The file must be an .vtt or .srt file!'] = 'Soubor musí být ve formátu .vtt nebo .srt!';
$t['The final charge uses the duration measured during processing. A connected Marketplace wallet is required.'] = 'Konečná částka vychází z délky naměřené během zpracování. Je vyžadována připojená peněženka Marketplace.';
$t['The following movie contains materials that are not suitable for children 17 and under.'] = 'Následující film obsahuje materiály, které nejsou vhodné pro děti do 17 let.';
$t['The following movie contains materials that may not be suitable for children 17 and under.'] = 'Následující film obsahuje materiály, které nemusí být vhodné pro děti do 17 let.';
$t['The form to signup will not exists'] = 'Formulář k registraci nebude existovat';
$t['The gift code has been canceled. If this is unexpected, please contact our support team.'] = 'Dárkový kód byl zrušen. Pokud to nečekáte, kontaktujte prosím naši podporu.';
$t['The gift code is currently inactive. Please check back later or contact support.'] = 'Dárkový kód je momentálně neaktivní. Zkuste to prosím později nebo kontaktujte podporu.';
$t['The information above corresponds to our official records and confirms the authenticity of this certificate.'] = 'Výše uvedené údaje odpovídají našim oficiálním záznamům a potvrzují pravost tohoto certifikátu.';
$t['The input stream contains invalid data. The source HLS may not be ready yet or the stream was interrupted.'] = 'Vstupní stream obsahuje neplatná data. Zdrojový HLS ještě nemusí být připraven nebo byl stream přerušen.';
$t['The installed PHP package lists both fixes, but this web process still runs the copy loaded before the update. Restart Apache or PHP-FPM.'] = 'Nainstalovaný balíček PHP obsahuje obě opravy, ale tento webový proces stále používá verzi načtenou před aktualizací. Restartujte Apache nebo PHP-FPM.';
$t['Their last plans add up to %s'] = 'Jejich poslední plány dávají dohromady %s';
$t['The list was limited to the first %s results.'] = 'Seznam byl omezen na prvních %s výsledků.';
$t['The live service could not complete the request. Please try again.'] = 'Služba živého vysílání nemohla dokončit požadavek. Zkuste to prosím znovu.';
$t['The live that was still being sent to this destination was stopped.'] = 'Živé vysílání, které se do tohoto cíle stále odesílalo, bylo zastaveno.';
$t['Theme for Style:'] = 'Theme for Style:';
$t['Themes'] = 'Motivy';
$t['The number of lines in both columns must be the same'] = 'Počet řádků v obou sloupcích musí být stejný';
$t['The original file for this video does not exists anymore'] = 'The original file for this video does not exists anymore';
$t['The Permissions Plugin is not installed. Please install it if you want to customize the permissions.'] = 'The Permissions Plugin is not installed. Please install it if you want to customize the permissions.';
$t['The plugin is disabled'] = 'The plugin is disabled';
$t['The program is empty'] = 'The program is empty';
$t['The purchase could not be completed. Your wallet payment was not deducted. Check your balance before trying again.'] = 'Nákup se nepodařilo dokončit. Platba z peněženky nebyla stržena. Před dalším pokusem zkontrolujte svůj zůstatek.';
$t['There\'s an unknown status associated with this gift code. Please contact support for assistance.'] = 'K tomuto dárkovému kódu je přiřazen neznámý stav. Kontaktujte prosím podporu.';
$t['There, you can set'] = 'Zde můžete nastavit';
$t['There are no notifications'] = 'Nejsou žádná oznámení';
$t['There are no upcoming events for this channel'] = 'Tento kanál nemá žádné nadcházející události';
$t['There are various kinds of media you can integrate here. They are working different'] = 'There are various kinds of media you can integrate here. They are working different';
$t['There are various kinds of media you can integrate here. They are working diffrent'] = 'Existují různé typy médií, které můžete použít. Fungují rozdílně';
$t['The recover pass does not match!'] = 'The recover pass does not match!';
$t['The regular form to signin will not exist, if you check this will only have social login or LDAP option'] = 'Klasický formulář pro přihlášení nebude existovat, pokud zapnete, budete mít možnost přihlásit se pouze pomocí sociálních sítí nebo LDAP';
$t['There is missing data to recover your password'] = 'There is missing data to recover your password';
$t['There is no Pay Per View plan yet. Create one in the Pay-Per-View plugin, PPV Plans tab.'] = 'Zatím neexistuje žádný plán Pay Per View. Vytvořte jej v pluginu Pay-Per-View na kartě PPV plány.';
$t['There is no plan that can hold videos yet. Create one in the PPV Plans tab, then come back here.'] = 'Zatím neexistuje žádný plán, který by mohl obsahovat videa. Vytvořte jej na kartě PPV plány a pak se sem vraťte.';
$t['There is no streaming now'] = 'Aktuálně neexistuje žádný stream';
$t['The release number and the AVideo database version are independent. Code update status is determined by commit history.'] = 'Číslo vydání a verze databáze AVideo jsou nezávislé. Stav aktualizace kódu se určuje podle historie commitů.';
$t['The request to the social network failed. Please try again later.'] = 'Požadavek na sociální síť selhal. Zkuste to prosím později.';
$t['The restreamer server cannot reach the destination. Check network connectivity.'] = 'Server restreameru se nemůže spojit s cílem. Zkontrolujte síťové připojení.';
$t['The same alert is repeated at most every %s while the problem continues.'] = 'Stejné upozornění se opakuje nejvýše každých %s, dokud problém trvá.';
$t['The same alert is repeated at most every few hours while the problem continues.'] = 'Stejné upozornění se opakuje nejvýše jednou za několik hodin, dokud problém trvá.';
$t['The selected camera or microphone is not available. Please choose another device.'] = 'Vybraná kamera nebo mikrofon není k dispozici. Zvolte prosím jiné zařízení.';
$t['The selected position is highlighted on a real page. Mobile preview changes only the ADs positions; the rest of the page uses your browser device.'] = 'Vybraná pozice je zvýrazněna na skutečné stránce. Mobilní náhled mění pouze pozice reklam; zbytek stránky používá zařízení vašeho prohlížeče.';
$t['The selected position is outlined on a real page of your site and follows the position you choose below. Mobile preview changes only the ADs positions; the rest of the page uses your browser device.'] = 'Vybraná pozice je zvýrazněna na skutečné stránce vašeho webu a odpovídá pozici, kterou zvolíte níže. Mobilní náhled mění pouze pozice reklam; zbytek stránky se řídí zařízením vašeho prohlížeče.';
$t['The site is currently offline due to a database issue. We are working to resolve the problem as quickly as possible.'] = 'Web je momentálně offline kvůli problému s databází. Pracujeme na co nejrychlejším vyřešení problému.';
$t['The site is temporarily unavailable because the server\'s disk is full. We are working on this issue and will be back shortly.'] = 'Web je dočasně nedostupný, protože disk serveru je plný. Na problému pracujeme a brzy budeme zpět.';
$t['The site is undergoing maintenance as the server\'s disk is nearing capacity. We are addressing the issue and will be back shortly.'] = 'Na webu probíhá údržba, protože disk serveru je téměř plný. Problém řešíme a brzy budeme zpět.';
$t['The site refused access. Renew the encoder account access and check its upload permissions.'] = 'Web odmítl přístup. Obnovte přístup účtu enkodéru a zkontrolujte jeho oprávnění k nahrávání.';
$t['The site will display only a login form to un authenticated users'] = 'Nepřihlášeným uživatelům se zobrazí pouze přihlašovací formulář';
$t['The source stream ended. If the live was stopped intentionally this is normal.'] = 'Zdrojový stream skončil. Pokud bylo živé vysílání zastaveno záměrně, je to normální.';
$t['The split is on: desktop visitors do not see this banner now, they see the left and right halves.'] = 'Rozdělení je zapnuté: návštěvníci na počítači nyní tento banner nevidí, vidí levou a pravou polovinu.';
$t['The stream has timestamp discontinuities. This can cause buffering or playback issues on the destination platform.'] = 'Stream obsahuje nespojitosti časových značek. To může způsobit načítání nebo problémy s přehráváním na cílové platformě.';
$t['The subtitle has not been copied to the player yet.'] = 'Titulky zatím nebyly zkopírovány do přehrávače.';
$t['The subtitle is already on the player.'] = 'Titulky už jsou v přehrávači.';
$t['The subtitle was copied to the player.'] = 'Titulky byly zkopírovány do přehrávače.';
$t['The subtitle will be available when processing finishes.'] = 'Titulky budou k dispozici po dokončení zpracování.';
$t['The upload could not be started. Please try again.'] = 'Nahrávání se nepodařilo spustit. Zkuste to prosím znovu.';
$t['The upload did not start. Click Resume to try again.'] = 'Nahrávání se nespustilo. Klikněte na Pokračovat a zkuste to znovu.';
$t['The upload to YouTube started. You can follow its progress below, it continues even if you close this window.'] = 'Nahrávání na YouTube začalo. Jeho průběh můžete sledovat níže, pokračuje i po zavření tohoto okna.';
$t['The upload was canceled.'] = 'Nahrávání bylo zrušeno.';
